<?php require_once __DIR__.'/includes/auth.php'; if(is_logged_in()) redirect(dashboard_redirect_path()); $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $username=trim($_POST['username']??'');$password=$_POST['password']??''; try{$s=db()->prepare('SELECT u.*,r.name role_name FROM users u JOIN roles r ON r.id=u.role_id WHERE u.username=? LIMIT 1');$s->execute([$username]);$u=$s->fetch();if($u && $u['status']==='Active' && password_verify($password,$u['password'])){session_regenerate_id(true);$_SESSION['user_id']=$u['id'];$_SESSION['user_name']=$u['full_name'];$_SESSION['user_role']=$u['role_name'];$_SESSION['role_id']=$u['role_id'];try{$l=db()->prepare('INSERT INTO login_logs(user_id,username,ip_address) VALUES(?,?,?)');$l->execute([$u['id'],$username,$_SERVER['REMOTE_ADDR']??'']);}catch(Throwable $e){} redirect(dashboard_redirect_path());}$error='Invalid credentials or inactive account.';}catch(Throwable $e){$error='Database is not ready. Import database.sql first.';}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Officer Login | LDA</title><link rel="stylesheet" href="assets/css/style.css"></head><body><div class="utility"><div class="inner"><span>LDA PROPERTY PORTAL</span><span>Secure officer access</span></div></div><main class="login-wrap"><section class="form-card login-card"><a class="btn btn-outline" href="index.php">← Back to Home</a><div class="eyebrow" style="margin-top:28px">Officer access</div><h1>Welcome back</h1><p class="muted">Sign in to manage LDA property services.</p><?php if($error):?><div class="alert"><?=e($error)?></div><?php endif;?><form method="post"><label class="form-label">Username</label><input class="form-control" name="username" required autofocus><label class="form-label">Password</label><input class="form-control" type="password" name="password" required><button class="btn btn-secondary" style="width:100%;margin-top:22px">Sign in</button></form></section></main></body></html>